import {
  type TeamHuntState,
  get_hint_resource_status,
} from "@hunt/public-client";
import { ConditionalTooltip } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import React, { useEffect, useState } from "react";
import { HintBadge, HintBadgeCompact } from "./HintBadge";

const HintLinkWrapper = ({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) => <div className={cn("inline-flex", className)}>{children}</div>;

export default function RoundHintLink({
  slug,
  teamState,
  variant = "long",
  className,
}: {
  slug: string;
  teamState: TeamHuntState;
  variant?: "long" | "short";
  className?: string;
}) {
  const roundState = teamState.rounds[slug];
  const hintsUnlockedAt = roundState?.hints_unlocked_at;

  const [unlocked, setUnlocked] = useState(
    hintsUnlockedAt && new Date(hintsUnlockedAt).getTime() < Date.now(),
  );

  useEffect(() => {
    if (hintsUnlockedAt && !unlocked) {
      const interval = setInterval(() => {
        if (new Date(hintsUnlockedAt).getTime() < Date.now()) {
          setUnlocked(true);
        }
      }, 5000);

      return () => {
        clearInterval(interval);
      };
    }
  }, [hintsUnlockedAt, unlocked]);

  const solved =
    get_hint_resource_status({ type: "round", slug }, teamState) === "solved";

  if (solved || !hintsUnlockedAt) {
    return null;
  }

  const BadgeComponent = variant === "short" ? HintBadgeCompact : HintBadge;

  const hintAvailableAt = new Date(hintsUnlockedAt).toLocaleString("en-US");

  return (
    <HintLinkWrapper className={className}>
      <ConditionalTooltip
        tooltip={
          unlocked
            ? "Ask for a hint"
            : `Hints will be available for this round at ${hintAvailableAt}`
        }
      >
        <BadgeComponent
          href={`/rounds/${slug}/hints`}
          disabled={!unlocked}
          aria-label="Hints"
        />
      </ConditionalTooltip>
    </HintLinkWrapper>
  );
}
