import { TERMINUS_TYPES, type TerminusType } from "@hunt/hunt-data";
import { twemojify as twemojifyOriginal } from "@hunt/shadcn";
import React, { type ReactNode, useMemo } from "react";
import { type TerminusResponseState } from "../types";
import TerminusErrorBox from "./TerminusError";
import TerminusInfoBox from "./TerminusInfo";
import { TerminusMessageBox } from "./TerminusMessageBox";

// Workaround for CI lint error where twemojify is typed as any/error
const twemojify = twemojifyOriginal as (
  text: string,
  className: string,
) => ReactNode[];

const ERROR_POSITIONS: Record<TerminusType, { x: number; y: number }> = {
  Zone1: { x: 249, y: 731 },
  Zone2: { x: 180, y: 324 },
  Zone3: { x: 542, y: 138 },
  Zone4: { x: 1089, y: 130 },
  Zone5: { x: 1522, y: 319 },
  Zone6: { x: 1402, y: 724 },
};

const PUZZLE_POSITIONS: Record<TerminusType, { x: number; y: number }> = {
  Zone1: { x: 100, y: 701 },
  Zone2: { x: 229, y: 434 },
  Zone3: { x: 542, y: 198 },
  Zone4: { x: 1089, y: 198 },
  Zone5: { x: 1422, y: 434 },
  Zone6: { x: 1522, y: 701 },
};

type TerminusMessagesProps = {
  response: TerminusResponseState | null;
};

export const TerminusMessages = ({ response }: TerminusMessagesProps) => {
  const processResult = (
    result: [string, ReactNode[], boolean][],
  ): [string, ReactNode, boolean][] => {
    return result.map(([key, message, isError]) => {
      const processedResult = message.map((messageComponent) => {
        if (typeof messageComponent !== "string") {
          return messageComponent;
        }

        // We do not convert the text to lowercase because we want to exclude
        // cases with all caps, since that will be user-input.
        const conversionRegex =
          /\b(Conversion|Converted|conversion|converted)\b/;
        const match = conversionRegex.exec(messageComponent);
        if (!match) {
          return messageComponent;
        }

        const beforeMatch = messageComponent.slice(0, match.index);
        const matchedText = messageComponent.slice(
          match.index,
          match.index + match[0].length,
        );
        const afterMatch = messageComponent.slice(
          match.index + match[0].length,
        );
        return (
          <div key={key}>
            {beforeMatch}
            <span className="text-term-light-blue">{matchedText}</span>
            {afterMatch}
          </div>
        );
      });

      return [key, processedResult, isError];
    });
  };

  // The typechecker seems to not be able to infer that all the keys of response.results
  // are of type TerminusType, but that's fine since we don't need them to be.
  const activeMessages: [string, ReactNode, boolean][] = useMemo(() => {
    if (response?.status !== "success") {
      return [];
    }
    const result: [string, ReactNode[], boolean][] = [];
    // We do this rather than using filter/map for typechecking reasons.
    for (const [key, r] of Object.entries(response.results)) {
      if (r.message === null) continue;

      result.push([
        key,
        twemojify(r.message, "h-3.5 mb-0.5"),
        r.status === "failure" || r.status === "no_puzzle",
      ]);
    }

    return processResult(result);
  }, [response]);

  return (
    <div className="flex flex-col gap-2">
      {activeMessages
        .filter(([key]) => key in ERROR_POSITIONS)
        .map(([key, message, isError]) =>
          isError ? (
            <TerminusErrorBox
              key={key}
              top={ERROR_POSITIONS[key as TerminusType].y}
              left={ERROR_POSITIONS[key as TerminusType].x}
              copyContentId={`terminus-message-error-${key}`}
            >
              {message}
            </TerminusErrorBox>
          ) : (
            <TerminusInfoBox
              key={key}
              top={ERROR_POSITIONS[key as TerminusType].y}
              left={ERROR_POSITIONS[key as TerminusType].x}
              copyContentId={`terminus-message-info-${key}`}
            >
              {message}
            </TerminusInfoBox>
          ),
        )}
    </div>
  );
};

type TerminusPuzzleContentProps = {
  contentList: React.ReactNode[];
};

export const TerminusPuzzleContent = ({
  contentList,
}: TerminusPuzzleContentProps) => {
  return (
    <div className="flex flex-col gap-2">
      {contentList.map((content, index) => {
        const type = TERMINUS_TYPES[index];
        return (
          <TerminusMessageBox
            key={type}
            top={PUZZLE_POSITIONS[type].y}
            left={PUZZLE_POSITIONS[type].x}
            className="flex items-center justify-center text-xl font-bold m-0 -translate-y-1/2 px-2"
            textClassName="max-h-none"
          >
            {content}
          </TerminusMessageBox>
        );
      })}
    </div>
  );
};
