import { erratumResourceKey, type TeamHuntState } from "@hunt/public-client";
import { cn } from "@hunt/styled-ui";
import React, { useCallback, useEffect, useRef, useState } from "react";
import { ErratumIcon } from "../../../../components/ErratumIcon";
import { NSFWIndicator } from "../../../../components/NSFWIndicator";
import RoundHintLink from "../../../../components/RoundHintLink";
import solvedMetaStar from "../assets/stars/solved_meta_star.svg";
import solvedStar from "../assets/stars/solved_star.svg";
import unsolvedMetaStar from "../assets/stars/unsolved_meta_star.svg";
import unsolvedStar from "../assets/stars/unsolved_star.svg";
import {
  BG_NATIVE_HEIGHT,
  BG_NATIVE_WIDTH,
  STAR_METADATA,
  STAR_TOGGLE_POSITION,
} from "../terminus_constants";
import type { TerminusPuzzleDisplay, TerminusResponseState } from "../types";

import "./terminus-stars.css";

const TOOLTIP_LINE_LENGTH_BY_PERCENT = 5;
const MIN_PADDING_FROM_EDGE = 10;
const TOP_MARGIN_PERCENT = 7;
const TERMINUS_SHOW_ALL_STARS_KEY = "terminus-show-all-stars";

type StarToggleProps = {
  isEnabled: boolean;
  onToggle?: () => void;
  className?: string;
  positioned?: boolean;
};

const StarToggle = ({
  isEnabled,
  onToggle,
  className,
  positioned = true,
}: StarToggleProps) => {
  return (
    <div
      className={cn(
        positioned && "absolute -translate-x-1/2 -translate-y-1/2",
        className,
      )}
      onClick={onToggle}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onToggle?.();
        }
      }}
      aria-pressed={isEnabled}
      aria-label={isEnabled ? "Show current stars only" : "Show all stars"}
      style={
        positioned
          ? {
              top: `${(STAR_TOGGLE_POSITION.y / BG_NATIVE_HEIGHT) * 100}%`,
              left: `${(STAR_TOGGLE_POSITION.x / BG_NATIVE_WIDTH) * 100}%`,
            }
          : undefined
      }
    >
      <div className="flex flex-col items-center gap-1">
        <div
          className={cn(
            "w-[54px] h-[28px] rounded-full flex items-center p-1 cursor-pointer transition-colors shadow-[inset_0_4px_4px_rgba(0,0,0,0.55)]",
            isEnabled ? "bg-[#569456]" : "bg-[#23273F]",
          )}
        >
          <div
            className={cn(
              "w-[22px] h-[22px] bg-[#B6D0F3] rounded-full transition-all duration-200 ease-in-out",
              isEnabled ? "translate-x-[24px]" : "translate-x-0",
            )}
          />
        </div>
      </div>
    </div>
  );
};

type StarTooltipProps = {
  puzzle: TerminusPuzzleDisplay;
  topPercent: number;
  leftPercent: number;
  line: {
    x1: number;
    y1: number;
    x2: number;
    y2: number;
  };
  isBelow: boolean;
  isMeta: boolean;
  onHeightMeasured?: (heightPercent: number) => void;
};

const StarTooltip = ({
  puzzle,
  topPercent,
  leftPercent,
  line,
  isBelow,
  isMeta,
  onHeightMeasured,
}: StarTooltipProps) => {
  const tooltipRef = useRef<HTMLDivElement>(null);
  const [adjustedLeft, setAdjustedLeft] = useState(leftPercent);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    // Reset visibility while calculating.
    setIsVisible(false);
    setAdjustedLeft(leftPercent);

    if (!tooltipRef.current) return;

    const tooltip = tooltipRef.current;
    const container = tooltip.offsetParent as HTMLElement;
    if (!container) return;

    // Use requestAnimationFrame to ensure layout is complete
    requestAnimationFrame(() => {
      if (!tooltipRef.current || !container) return;

      const rect = tooltipRef.current.getBoundingClientRect();
      const containerRect = container.getBoundingClientRect();
      const viewportWidth = window.innerWidth;

      // Measure and report tooltip height as percentage of container
      if (onHeightMeasured) {
        const heightPercent = (rect.height / containerRect.height) * 100;
        onHeightMeasured(heightPercent);
      }

      const tooltipCenterX = rect.left + rect.width / 2;
      const tooltipHalfWidth = rect.width / 2;

      let newLeft = leftPercent;

      // Check if tooltip would overflow left or right
      if (tooltipCenterX - tooltipHalfWidth < MIN_PADDING_FROM_EDGE) {
        // Shift right to keep it on screen
        const shiftPixels =
          MIN_PADDING_FROM_EDGE - (tooltipCenterX - tooltipHalfWidth);
        const shiftPercent = (shiftPixels / containerRect.width) * 100;
        newLeft = leftPercent + shiftPercent;
      } else if (
        tooltipCenterX + tooltipHalfWidth >
        viewportWidth - MIN_PADDING_FROM_EDGE
      ) {
        // Shift left to keep it on screen
        const shiftPixels =
          tooltipCenterX +
          tooltipHalfWidth -
          (viewportWidth - MIN_PADDING_FROM_EDGE);
        const shiftPercent = (shiftPixels / containerRect.width) * 100;
        newLeft = leftPercent - shiftPercent;
      }

      setAdjustedLeft(newLeft);
      setIsVisible(true);
    });
  }, [leftPercent, topPercent, puzzle.puzzle.title, onHeightMeasured]);

  return (
    <>
      {/* Dotted line connecting star to tooltip */}
      <svg
        className={cn(
          "absolute pointer-events-none top-0 left-0 w-full h-full z-10",
        )}
        style={{
          visibility: isVisible ? "visible" : "hidden",
        }}
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
      >
        <line
          className={cn("stroke-accent", isMeta && "stroke-term-orange")}
          x1={line.x1}
          y1={line.y1}
          x2={line.x2}
          y2={line.y2}
          strokeWidth="0.2"
          strokeDasharray="1,1"
        />
      </svg>
      <div
        ref={tooltipRef}
        className={cn(
          "absolute flex flex-col items-center pointer-events-none font-code text-center text-sm -translate-x-1/2 py-2 px-3 text-accent whitespace-nowrap bg-black/75 border-accent z-10",
          isMeta && "text-term-orange border-term-orange",
          isBelow ? "translate-y-0 border-t-2" : "-translate-y-full border-b-2",
        )}
        style={{
          top: `${topPercent}%`,
          left: `${adjustedLeft}%`,
          visibility: isVisible ? "visible" : "hidden",
        }}
      >
        <div className="flex items-center gap-1.5">
          {puzzle.puzzle.nsfw && <NSFWIndicator size="sm" />}
          {puzzle.puzzle.title}
        </div>
        {puzzle.puzzle.answer && (
          <div className="text-term-green font-bold">
            {puzzle.puzzle.answer}
          </div>
        )}
      </div>
    </>
  );
};

type TerminusStarImageProps = {
  puzzle: TerminusPuzzleDisplay;
  isMetaStar?: boolean;
  className?: string;
};

export const TerminusStarImage = ({
  puzzle,
  isMetaStar = false,
  className,
}: TerminusStarImageProps) => {
  let starSrc = puzzle.puzzle.answer ? solvedStar : unsolvedStar;
  if (isMetaStar) {
    starSrc = puzzle.puzzle.answer ? solvedMetaStar : unsolvedMetaStar;
  }

  const starWidth = isMetaStar
    ? STAR_METADATA.meta.width
    : STAR_METADATA[puzzle.puzzle.answer ? "solved" : "unsolved"].width;
  let style: React.CSSProperties = {};
  if (!className) {
    style = { width: `${starWidth}px` };
  }

  return (
    <img
      src={starSrc}
      alt={puzzle.puzzle.title}
      className={cn("select-none", className)}
      style={style}
    />
  );
};

type TerminusStarProps = {
  puzzle: TerminusPuzzleDisplay;
  isInCurrentUniverse?: boolean;
  isMetaStar?: boolean;
};

const TerminusStar = ({
  puzzle,
  isInCurrentUniverse = false,
  isMetaStar = false,
}: TerminusStarProps) => {
  const [isHovered, setIsHovered] = useState(false);
  const [tooltipHeightPercent, setTooltipHeightPercent] = useState<
    number | null
  >(null);
  const [isBelow, setIsBelow] = useState(false);

  const starWidth = isMetaStar
    ? STAR_METADATA.meta.width
    : STAR_METADATA[puzzle.puzzle.answer ? "solved" : "unsolved"].width;

  // Calculate positions
  const starTopPercent = (puzzle.pos.top / BG_NATIVE_HEIGHT) * 100;
  const starLeftPercent = (puzzle.pos.left / BG_NATIVE_WIDTH) * 100;
  const starWidthPercent = (starWidth / BG_NATIVE_WIDTH) * 100;
  const starHeightPercent = (starWidth / BG_NATIVE_HEIGHT) * 100;

  // Calculate isBelow based on tooltip height
  // When tooltip is above, it uses -translate-y-full, so we need to account for tooltip height
  useEffect(() => {
    const tooltipTopPercentIfAbove =
      starTopPercent - TOOLTIP_LINE_LENGTH_BY_PERCENT;
    if (tooltipHeightPercent !== null) {
      // The actual top edge of the tooltip when above would be tooltipTopPercentIfAbove - tooltipHeightPercent
      const tooltipTopEdgeIfAbove =
        tooltipTopPercentIfAbove - tooltipHeightPercent;
      const tooltipWouldBeAboveTop = tooltipTopEdgeIfAbove < TOP_MARGIN_PERCENT;
      setIsBelow(tooltipWouldBeAboveTop);
    } else {
      // Initial estimate without height (will be refined when height is measured)
      const tooltipWouldBeAboveTop =
        starTopPercent - TOOLTIP_LINE_LENGTH_BY_PERCENT < TOP_MARGIN_PERCENT;
      setIsBelow(tooltipWouldBeAboveTop);
    }
  }, [starTopPercent, tooltipHeightPercent]);

  const handleHeightMeasured = useCallback((heightPercent: number) => {
    setTooltipHeightPercent(heightPercent);
  }, []);

  // Calculate tooltip position
  const tooltipTopPercent = isBelow
    ? starTopPercent + starHeightPercent + TOOLTIP_LINE_LENGTH_BY_PERCENT
    : starTopPercent - TOOLTIP_LINE_LENGTH_BY_PERCENT;
  const tooltipLeftPercent = starLeftPercent + starWidthPercent / 2;

  // Line connection points
  const starLineX = starLeftPercent + starWidthPercent / 2;
  const starLineY = isBelow
    ? starTopPercent + starHeightPercent // Bottom of star
    : starTopPercent; // Top of star
  const tooltipLineX = starLineX;
  // When above: tooltipTopPercent is visual bottom (tooltip translated up)
  // When below: tooltipTopPercent is visual top (tooltip not translated)
  const tooltipLineY = tooltipTopPercent;

  return (
    <>
      <a
        className={cn(
          "absolute cursor-pointer",
          isMetaStar ? "terminus-meta-star" : "terminus-star",
          isInCurrentUniverse ? "in-current-universe" : "brightness-75",
          puzzle.puzzle.answer ? "solved" : "unsolved",
        )}
        style={{
          top: `${starTopPercent}%`,
          left: `${starLeftPercent}%`,
          width: `${starWidthPercent}%`,
        }}
        href={`/puzzles/${puzzle.puzzle.slug}`}
        onMouseEnter={() => {
          setIsHovered(true);
        }}
        onMouseLeave={() => {
          setIsHovered(false);
        }}
      >
        <TerminusStarImage puzzle={puzzle} isMetaStar={isMetaStar} />
      </a>
      {isHovered && (
        <StarTooltip
          puzzle={puzzle}
          topPercent={tooltipTopPercent}
          leftPercent={tooltipLeftPercent}
          line={{
            x1: starLineX,
            y1: starLineY,
            x2: tooltipLineX,
            y2: tooltipLineY,
          }}
          isBelow={isBelow}
          isMeta={isMetaStar}
          onHeightMeasured={handleHeightMeasured}
        />
      )}
    </>
  );
};

type TerminusStarsProps = {
  puzzles: TerminusPuzzleDisplay[];
  response: TerminusResponseState | null;
  teamState: TeamHuntState;
};

const TerminusStars = ({
  puzzles,
  response,
  teamState,
}: TerminusStarsProps) => {
  const [showAllStars, setShowAllStars] = useState<boolean | undefined>(
    undefined,
  );

  useEffect(() => {
    // Initialize from localStorage, defaulting to true if not found.
    const stored = localStorage.getItem(TERMINUS_SHOW_ALL_STARS_KEY);
    setShowAllStars(stored !== null ? stored === "true" : true);
  }, []);

  useEffect(() => {
    if (showAllStars === undefined) return;
    // Save to localStorage whenever showAllStars changes.
    localStorage.setItem(TERMINUS_SHOW_ALL_STARS_KEY, String(showAllStars));
  }, [showAllStars]);

  const handleStarToggle = useCallback(() => {
    setShowAllStars((prev) => !prev);
  }, []);

  const starTogglePositionStyle = {
    top: `${(STAR_TOGGLE_POSITION.y / BG_NATIVE_HEIGHT) * 100}%`,
    left: `${(STAR_TOGGLE_POSITION.x / BG_NATIVE_WIDTH) * 100}%`,
  };
  const hasRoundErratum =
    teamState.errata?.includes(
      erratumResourceKey({ type: "round", slug: "terminus" }),
    ) ?? false;

  return (
    <>
      {puzzles.length > 0 && showAllStars !== undefined && (
        <>
          <div
            className="absolute -translate-x-1/2 -translate-y-1/2 flex flex-col items-center gap-1"
            style={starTogglePositionStyle}
          >
            <ErratumIcon
              resource={{ type: "round", slug: "terminus" }}
              hasErratum={hasRoundErratum}
              iconClassName="h-7 w-7 text-rose-500"
            />
            <StarToggle
              isEnabled={showAllStars}
              onToggle={handleStarToggle}
              positioned={false}
            />
          </div>
          <div className="absolute top-20 right-4 md:top-24 md:right-8 z-10">
            <RoundHintLink
              slug="terminus"
              teamState={teamState}
              variant="short"
            />
          </div>
        </>
      )}
      {puzzles
        .sort((a, b) => {
          const regionDiff = (a.region ?? Infinity) - (b.region ?? Infinity);
          if (regionDiff !== 0) return regionDiff;
          // Order alphabetically within a region.
          return a.puzzle.title.localeCompare(b.puzzle.title);
        })
        .map((puzzle) => {
          if (puzzle.is_final_meta) {
            return null;
          }
          const isInCurrentUniverse =
            response?.status === "success" &&
            Object.values(response?.results).some((result) => {
              return (
                (result.status === "puzzle_list" &&
                  result.puzzle_slugs.includes(puzzle.puzzle.slug)) ||
                (result.status === "meta" &&
                  result.puzzle_slug === puzzle.puzzle.slug)
              );
            });

          if (!showAllStars && !isInCurrentUniverse) {
            return null;
          }

          return (
            <TerminusStar
              key={puzzle.puzzle.slug}
              puzzle={puzzle}
              isInCurrentUniverse={isInCurrentUniverse}
              isMetaStar={puzzle.is_meta}
            />
          );
        })}
    </>
  );
};

export default TerminusStars;
