import { cn } from "@hunt/styled-ui";
import { Lightbulb } from "lucide-react";
import React from "react";

type HintBadgeVariant = "long" | "short";

type HintBadgeProps = Omit<
  React.AnchorHTMLAttributes<HTMLAnchorElement>,
  "children"
> & {
  variant?: HintBadgeVariant;
  disabled?: boolean;
};

const HintBadgeBase = React.forwardRef<HTMLAnchorElement, HintBadgeProps>(
  (
    {
      className,
      variant = "long",
      "aria-label": ariaLabel,
      disabled = false,
      href,
      tabIndex,
      onClick,
      role,
      ...anchorProps
    },
    ref,
  ) => {
    const isLong = variant === "long";
    const handleClick: React.MouseEventHandler<HTMLAnchorElement> = (event) => {
      if (disabled) {
        event.preventDefault();
        event.stopPropagation();
        return;
      }

      onClick?.(event);
    };

    return (
      <a
        {...anchorProps}
        ref={ref}
        aria-label={ariaLabel ?? "Hints"}
        aria-disabled={disabled || undefined}
        className={cn(
          "group inline-flex h-12 items-center justify-center gap-0.5 rounded-lg border-2 border-[#FFE100] bg-[#2C599C] text-[#FFE100] no-underline hover:no-underline shadow-[0_0_6px_rgba(0,0,0,0.5)] transition-colors duration-150",
          disabled
            ? "cursor-not-allowed opacity-60 hover:border-[#FFE100] hover:bg-[#2C599C] hover:text-[#FFE100] hover:shadow-[0_0_6px_rgba(0,0,0,0.5)]"
            : "hover:border-[#2C599C] hover:bg-[#FFE100] hover:text-[#2C599C]",
          isLong ? "w-28" : "w-12",
          className,
        )}
        href={disabled ? undefined : href}
        onClick={handleClick}
        role={role ?? (disabled ? "link" : undefined)}
        tabIndex={disabled ? (tabIndex ?? 0) : tabIndex}
      >
        {isLong ? (
          <div className="flex flex-col justify-center font-normal not-italic">
            <span className="text-lg leading-normal">Hints</span>
          </div>
        ) : null}
        <Lightbulb className="h-5 w-5" />
      </a>
    );
  },
);

HintBadgeBase.displayName = "HintBadgeBase";

export const HintBadge = React.forwardRef<
  HTMLAnchorElement,
  Omit<HintBadgeProps, "variant">
>((props, ref) => <HintBadgeBase ref={ref} {...props} variant="long" />);

HintBadge.displayName = "HintBadge";

export const HintBadgeCompact = React.forwardRef<
  HTMLAnchorElement,
  Omit<HintBadgeProps, "variant">
>((props, ref) => <HintBadgeBase ref={ref} {...props} variant="short" />);

HintBadgeCompact.displayName = "HintBadgeCompact";
