import { type TeamHuntState } from "@hunt/public-client";
import { cn } from "@hunt/styled-ui";
import { ChevronDown, ChevronRight } from "lucide-react";
import React, { useMemo, useState } from "react";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import { TerminusStarImage } from "./TerminusInterface/TerminusStars";
import { getRegionForPuzzle } from "./terminus_slot_data";
import type { TerminusState } from "./types";

type TerminusPuzzleListProps = {
  state: TerminusState;
  teamState: TeamHuntState;
  showAllPuzzles?: boolean;
  onToggleShowAll?: () => void;
};

type RegionGroup = {
  region: number;
  puzzles: TerminusState["puzzles"];
  meta: TerminusState["puzzles"][number] | null;
};

type PuzzleLinkProps = {
  puzzle: TerminusState["puzzles"][number];
  isMetaStar?: boolean;
  className?: string;
};

const PuzzleLink = ({
  puzzle,
  isMetaStar = false,
  className,
}: PuzzleLinkProps) => {
  return (
    <a
      role="button"
      href={`/puzzles/${puzzle.puzzle.slug}`}
      className={cn(
        "flex items-center gap-2 px-2 py-1 border-dashed bg-black font-code text-white border-2 border-term-border-blue hover:bg-term-screen-hover hover:text-white transition focus-visible:bg-term-screen-hover focus-visible:text-white",
        className,
      )}
    >
      <div className="flex-1 flex items-center gap-2">
        <div className="w-12 h-12 flex items-center justify-center">
          <TerminusStarImage
            puzzle={puzzle}
            isMetaStar={isMetaStar}
            className={cn(
              isMetaStar
                ? "w-12 h-12"
                : puzzle.puzzle.answer
                  ? "w-6 h-6"
                  : "w-8 h-8",
            )}
          />
        </div>
        <span className="text-left underline">{puzzle.puzzle.title}</span>
      </div>
      {puzzle.puzzle.answer && (
        <span className="ml-2 text-term-green font-bold text-right flex-shrink-0">
          {puzzle.puzzle.answer}
        </span>
      )}
    </a>
  );
};

type ToggleButtonProps = {
  children: React.ReactNode;
  isCollapsed: boolean;
  onClick: () => void;
  className?: string;
  ariaLabel?: string;
};

const ToggleButton = ({
  children,
  isCollapsed,
  onClick,
  className,
  ariaLabel,
}: ToggleButtonProps) => {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "flex items-center gap-4 w-full px-4 py-2 border-2 border-dashed border-term-border-blue bg-black",
        className,
      )}
      aria-label={ariaLabel}
    >
      {isCollapsed ? (
        <ChevronRight className="w-10 h-10 text-term-border-blue" />
      ) : (
        <ChevronDown className="w-10 h-10 text-term-border-blue" />
      )}
      {children}
    </button>
  );
};

const ShowAllToggle = ({
  enabled,
  onToggle,
}: {
  enabled: boolean;
  onToggle?: () => void;
}) => {
  return (
    <button
      type="button"
      onClick={onToggle}
      className="flex items-center gap-3 text-sm uppercase tracking-wide text-white"
      aria-pressed={enabled}
      aria-label={enabled ? "Show unlocked puzzles only" : "Show all puzzles"}
    >
      <span>
        {enabled ? "Showing all puzzles" : "Showing unlocked puzzles"}
      </span>
      <div
        className={cn(
          "w-[54px] h-[28px] rounded-full flex items-center p-1 cursor-pointer transition-colors shadow-[inset_0_4px_4px_rgba(0,0,0,0.55)]",
          enabled ? "bg-[#569456]" : "bg-[#23273F]",
        )}
      >
        <div
          className={cn(
            "w-[22px] h-[22px] bg-[#B6D0F3] rounded-full transition-all duration-200 ease-in-out",
            enabled ? "translate-x-[24px]" : "translate-x-0",
          )}
        />
      </div>
    </button>
  );
};

const TerminusPuzzleList = ({
  state,
  teamState,
  showAllPuzzles,
  onToggleShowAll,
}: TerminusPuzzleListProps) => {
  const [collapsedRegions, setCollapsedRegions] = useState<Set<number>>(
    new Set<number>(),
  );

  const regionGroups = useMemo(() => {
    const groups = new Map<number, RegionGroup>();

    // Initialize all regions
    for (let i = 1; i <= 6; i++) {
      groups.set(i, {
        region: i,
        puzzles: [],
        meta: null,
      });
    }

    // Add final meta if it exists (doesn't belong to a region)
    const finalMeta = state.meta;

    // Group puzzles by region
    state.puzzles.forEach((puzzle) => {
      // Skip the final meta
      if (finalMeta && puzzle.puzzle.slug === finalMeta.puzzle.slug) {
        return;
      }

      const region = getRegionForPuzzle(puzzle.puzzle.slug, teamState);
      if (region) {
        const group = groups.get(region);
        if (group) {
          // Check if this puzzle is a meta
          const slot = Object.values(teamState.rounds.terminus.slots).find(
            (slotData) => slotData.slug === puzzle.puzzle.slug,
          );
          if (slot?.is_meta) {
            group.meta = puzzle;
          } else {
            group.puzzles.push(puzzle);
          }
        }
      }
    });

    return Array.from(groups.values()).filter(
      (group) => group.puzzles.length > 0 || group.meta !== null,
    );
  }, [state, teamState]);

  const toggleRegion = (region: number) => {
    setCollapsedRegions((prev) => {
      const next = new Set(prev);
      if (next.has(region)) {
        next.delete(region);
      } else {
        next.add(region);
      }
      return next;
    });
  };

  const solutionAvailable =
    IS_STATIC_SITE ||
    (teamState.gates_satisfied?.includes("solutions_released") ?? false);

  return (
    <div className="bg-term-light-blue font-code p-8 flex flex-col items-center gap-4">
      {(showAllPuzzles !== undefined || solutionAvailable) && (
        <div className="w-full max-w-3xl flex flex-wrap items-center justify-between gap-4 rounded-sm border border-dashed border-term-border-blue bg-black/70 px-4 py-3">
          {showAllPuzzles !== undefined && (
            <ShowAllToggle
              enabled={showAllPuzzles}
              onToggle={onToggleShowAll}
            />
          )}
          {solutionAvailable && (
            <a
              href="/rounds/terminus/solution"
              className="ml-auto text-sm uppercase tracking-wide text-term-green underline hover:text-term-green/80"
            >
              View round solution
            </a>
          )}
        </div>
      )}

      {state.meta && (
        <div className="w-full max-w-xl">
          <PuzzleLink
            puzzle={state.meta}
            isMetaStar
            className="px-3 py-2 hover:border-term-border-blue w-full flex-col text-3xl font-bold"
          />
        </div>
      )}

      {regionGroups.length === 0 && (
        <div className="w-full max-w-3xl border border-dashed border-term-border-blue bg-black/60 px-6 py-6 text-center text-white text-sm">
          <p>No puzzles are unlocked yet.</p>
          {showAllPuzzles === false && (
            <p className="mt-2 text-term-border-blue">
              Toggle &quot;Show all puzzles&quot; to browse the full list.
            </p>
          )}
        </div>
      )}

      {regionGroups.map((group) => {
        const isCollapsed = collapsedRegions.has(group.region);
        const hasContent = group.puzzles.length > 0 || group.meta !== null;

        if (!hasContent) return null;

        const regionTitle = (
          group.puzzles[0] || group.meta
        )?.puzzle.title.split(":")[0];

        return (
          <div key={group.region} className="w-full max-w-3xl overflow-hidden">
            <ToggleButton
              onClick={() => {
                toggleRegion(group.region);
              }}
              isCollapsed={isCollapsed}
              ariaLabel={isCollapsed ? "Expand region" : "Collapse region"}
              className="text-2xl font-bold"
            >
              {regionTitle}
            </ToggleButton>
            {!isCollapsed && (
              <div className="flex text-lg items-start gap-2 p-3 bg-black/50 border-b-2 border-x-2 border-dashed border-term-border-blue">
                <div className="flex flex-col gap-2 w-full ml-10">
                  {group.meta && <PuzzleLink puzzle={group.meta} isMetaStar />}
                  {group.puzzles.map((puzzle) => (
                    <PuzzleLink key={puzzle.puzzle.slug} puzzle={puzzle} />
                  ))}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default TerminusPuzzleList;
