import { cn } from "@hunt/styled-ui";
import { TriangleAlert } from "lucide-react";
import React from "react";

type NSFWIndicatorProps = {
  size?: "sm" | "md" | "lg" | "xl";
  className?: string;
  iconClassName?: string;
};

export const NSFWIndicator: React.FC<NSFWIndicatorProps> = ({
  size = "md",
  className = "",
  iconClassName = "",
}) => {
  const sizeClasses = {
    sm: "w-4 h-4",
    md: "w-5 h-5",
    lg: "w-6 h-6",
    xl: "w-8 h-8",
  };

  const iconSize = sizeClasses[size];

  return (
    <span className={cn("relative group text-xs text-red-500", className)}>
      <TriangleAlert className={cn(iconSize, "text-red-600", iconClassName)} />
      <span className="absolute left-1/2 -translate-x-1/2 bottom-full mb-2 px-2 py-1 rounded bg-white text-black text-xs shadow border border-gray-200 opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-10 whitespace-nowrap">
        Mature Content
      </span>
    </span>
  );
};

export default NSFWIndicator;
