import { type ErratumResource } from "@hunt/public-client";
import { ConditionalTooltip } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { FilePenLine } from "lucide-react";
import React from "react";
import { useHasErratum } from "./ErrataContext";

const RESOURCE_LABELS: Record<ErratumResource["type"], string> = {
  puzzle: "puzzle",
  task: "task",
  round: "round",
  clue: "clue",
  quest: "quest",
  tile_level: "level",
};

type ErratumIconProps = {
  resource: ErratumResource;
  hasErratum?: boolean;
  className?: string;
  iconClassName?: string;
  tooltipClassName?: string;
  side?: "top" | "bottom" | "left" | "right";
  align?: "start" | "center" | "end";
};

export const ErratumIcon = ({
  resource,
  hasErratum,
  className,
  iconClassName,
  tooltipClassName,
  side,
  align,
}: ErratumIconProps) => {
  const visible = useHasErratum(resource, hasErratum);
  if (!visible) {
    return null;
  }
  const label = RESOURCE_LABELS[resource.type];
  const tooltip = (
    <div className="flex flex-col gap-1 text-sm">
      <span>Erratum issued for this {label}.</span>
      <a
        href="/activity_log"
        className="underline text-accent hover:text-accent"
        target="_blank"
        rel="noopener noreferrer"
      >
        View activity log
      </a>
    </div>
  );

  return (
    <ConditionalTooltip
      tooltip={tooltip}
      className={tooltipClassName}
      side={side}
      align={align}
    >
      <span
        className={cn("inline-flex items-center", className)}
        aria-label={`Erratum issued for this ${label}`}
      >
        <FilePenLine
          className={cn("h-5 w-5 text-rose-500", iconClassName)}
          aria-hidden="true"
        />
      </span>
    </ConditionalTooltip>
  );
};
