import { TERMINUS_META_SLUGS } from "@hunt/hunt-data";
import { newClient, type TeamHuntState } from "@hunt/public-client";
import {
  type ResolvedCutsceneContent,
  CutsceneDisplay,
} from "@hunt/puzzle-components";
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  getTerminusInputLengthError,
  normalizeTerminusValue,
} from "../../../../utils/terminus";
import { TeamStateProvider } from "../../../components/TeamStateProvider";
import { useSolvedPuzzlesState } from "../../../components/puzzleSolveLocalState";
import apiUrl from "../../../utils/apiUrl";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import {
  TerminusBackgroundWrapper,
  TerminusInteractiveScreens,
} from "./TerminusInterface/TerminusInterface";
import TerminusStars from "./TerminusInterface/TerminusStars";
import { TerminusMessages } from "./TerminusMessageBox/TerminusMessages";
import TerminusPuzzleList from "./TerminusPuzzleList";
import {
  applyTerminusSubmission,
  buildTerminusResponseFromEntry,
  getLatestTravelLogEntry,
  loadTerminusLocalState,
  saveTerminusLocalState,
  type TerminusLocalState,
} from "./terminusLocalState";
import { type TerminusResponseState, type TerminusState } from "./types";

const TERMINUS_SHOW_ALL_PUZZLES_KEY = "terminus-show-all-puzzles";

const TerminusBody = ({
  state,
  teamState,
  initialTerminusResponse,
  cutsceneContent,
}: {
  state: TerminusState;
  teamState: TeamHuntState;
  initialTerminusResponse?: TerminusResponseState | null;
  cutsceneContent?: ResolvedCutsceneContent[];
}) => {
  const [updateTerminusResponse, setUpdateTerminusResponse] =
    useState<TerminusResponseState | null>(initialTerminusResponse ?? null);
  const [rateLimitEndTimestamp, setRateLimitEndTimestamp] = useState<
    string | null
  >(null);
  const [clientError, setClientError] = useState<string | null>(null);
  const [updateTerminusLoading, setUpdateTerminusLoading] = useState(false);
  const [inputValue, setInputValue] = useState("");
  const previousUnlockedCountRef = useRef(state.progress.unlocked.length);
  const { solvedMap } = useSolvedPuzzlesState();
  const [localTerminusState, setLocalTerminusState] =
    useState<TerminusLocalState | null>(null);
  const [showAllPuzzles, setShowAllPuzzles] = useState(false);

  useEffect(() => {
    if (
      initialTerminusResponse !== undefined &&
      initialTerminusResponse !== null
    ) {
      if (!IS_STATIC_SITE) {
        setUpdateTerminusResponse(initialTerminusResponse);
      }
    }
  }, [initialTerminusResponse]);

  useEffect(() => {
    if (IS_STATIC_SITE) {
      return;
    }
    const unlockedCount = state.progress.unlocked.length;
    if (previousUnlockedCountRef.current === unlockedCount) {
      return;
    }
    previousUnlockedCountRef.current = unlockedCount;

    if (IS_STATIC_SITE) {
      return;
    }

    let isActive = true;
    void (async () => {
      try {
        const apiClient = newClient(apiUrl(), undefined);
        const result = await apiClient.getTerminus();
        if (!isActive) return;
        if (result.status === 200) {
          setUpdateTerminusResponse(result.body);
          setClientError(null);
        } else {
          setUpdateTerminusResponse(null);
        }
      } catch {
        if (!isActive) return;
        setUpdateTerminusResponse(null);
      }
    })();

    return () => {
      isActive = false;
    };
  }, [state.progress.unlocked.length]);

  useEffect(() => {
    if (!IS_STATIC_SITE) return;
    let isActive = true;
    void (async () => {
      const stored = await loadTerminusLocalState();
      if (!isActive) return;
      setLocalTerminusState(stored);
    })();
    return () => {
      isActive = false;
    };
  }, []);

  useEffect(() => {
    if (!IS_STATIC_SITE) return;
    const stored = localStorage.getItem(TERMINUS_SHOW_ALL_PUZZLES_KEY);
    if (stored !== null) {
      setShowAllPuzzles(stored === "true");
    }
  }, []);

  useEffect(() => {
    if (!IS_STATIC_SITE) return;
    localStorage.setItem(TERMINUS_SHOW_ALL_PUZZLES_KEY, String(showAllPuzzles));
  }, [showAllPuzzles]);

  useEffect(() => {
    if (!IS_STATIC_SITE || !localTerminusState) return;
    const latestEntry = getLatestTravelLogEntry(localTerminusState);
    if (latestEntry) {
      setUpdateTerminusResponse(buildTerminusResponseFromEntry(latestEntry));
      return;
    }
    if (initialTerminusResponse) {
      setUpdateTerminusResponse(initialTerminusResponse);
      return;
    }
    setUpdateTerminusResponse(null);
  }, [initialTerminusResponse, localTerminusState]);

  const unlockedSlugs = useMemo(() => {
    if (!IS_STATIC_SITE) {
      return state.progress.unlocked;
    }
    const base = localTerminusState?.unlocked ?? [];
    if (base.includes("mixed_media")) {
      return base;
    }
    // Terminus final meta (mixed_media) unlocks when 5 of the 6 submetas are solved.
    // It is not added automatically on the static site, so we add it here.
    const solvedSubmetaCount = TERMINUS_META_SLUGS.filter((slug) =>
      state.puzzles.some(
        (p) => p.puzzle.slug === slug && Boolean(p.puzzle.answer),
      ),
    ).length;
    if (solvedSubmetaCount >= 5) {
      return [...base, "mixed_media"];
    }
    return base;
  }, [localTerminusState, state.progress.unlocked, state.puzzles]);

  const unlockedSet = useMemo(() => {
    return new Set(unlockedSlugs);
  }, [unlockedSlugs]);

  const solvedSlugs = IS_STATIC_SITE
    ? state.puzzles
        .filter((puzzle) => Boolean(puzzle.puzzle.answer))
        .map((puzzle) => puzzle.puzzle.slug)
    : state.progress.solved;

  const unlockedPuzzles = state.puzzles.filter((puzzle) =>
    unlockedSet.has(puzzle.puzzle.slug),
  );

  const listPuzzles = IS_STATIC_SITE
    ? showAllPuzzles
      ? state.puzzles
      : unlockedPuzzles
    : state.puzzles;

  const metaState = IS_STATIC_SITE
    ? state.meta && (showAllPuzzles || unlockedSet.has(state.meta.puzzle.slug))
      ? state.meta
      : null
    : state.meta;

  const interfaceState = IS_STATIC_SITE
    ? {
        ...state,
        puzzles: unlockedPuzzles,
        meta: metaState,
        progress: { unlocked: unlockedSlugs, solved: solvedSlugs },
      }
    : state;

  const listState = IS_STATIC_SITE
    ? {
        ...state,
        puzzles: listPuzzles,
        meta: metaState,
        progress: { unlocked: unlockedSlugs, solved: solvedSlugs },
      }
    : state;

  const currentUniverse = updateTerminusResponse?.normalized_input ?? null;

  const starPuzzles = useMemo(() => {
    if (IS_STATIC_SITE && showAllPuzzles) {
      return state.puzzles;
    }
    return unlockedPuzzles;
  }, [showAllPuzzles, state.puzzles, unlockedPuzzles]);

  const handleUpdateTerminusSubmit = useCallback(
    (input: string) => {
      const normalizedInput = normalizeTerminusValue(input);
      if (normalizedInput === "") {
        setClientError("Please enter a destination before submitting.");
        setRateLimitEndTimestamp(null);
        return;
      }

      const lengthError = getTerminusInputLengthError(normalizedInput);
      if (lengthError) {
        setClientError(lengthError);
        setRateLimitEndTimestamp(null);
        return;
      }

      if (currentUniverse !== null && normalizedInput === currentUniverse) {
        setClientError("You are already in that universe.");
        setRateLimitEndTimestamp(null);
        return;
      }

      setUpdateTerminusLoading(true);
      setClientError(null);
      setRateLimitEndTimestamp(null);
      if (IS_STATIC_SITE) {
        void (async () => {
          try {
            const currentState =
              localTerminusState ?? (await loadTerminusLocalState());
            const { nextState, response } = applyTerminusSubmission({
              input: normalizedInput,
              currentState,
              basePuzzles: state.puzzles,
              solvedMap,
            });
            await saveTerminusLocalState(nextState);
            setLocalTerminusState(nextState);
            setUpdateTerminusResponse(response);
            setInputValue("");
          } catch {
            setUpdateTerminusResponse(null);
            setClientError("Failed to update Terminus locally.");
          } finally {
            setUpdateTerminusLoading(false);
          }
        })();
        return;
      }
      void (async () => {
        try {
          const apiClient = newClient(apiUrl(), undefined);
          const result = await apiClient.updateTerminus({
            body: { state: input },
          });
          if (result.status === 200) {
            setUpdateTerminusResponse(result.body);
            setInputValue("");
          } else if (result.status === 429) {
            const retryAt = new Date(result.body.retryAfter);
            setRateLimitEndTimestamp(retryAt.toLocaleTimeString());
          } else {
            setUpdateTerminusResponse(null);
          }
        } catch {
          setUpdateTerminusResponse(null);
        } finally {
          setUpdateTerminusLoading(false);
        }
      })();
    },
    [currentUniverse, localTerminusState, solvedMap, state.puzzles],
  );

  return (
    <TeamStateProvider teamState={teamState}>
      <div className="h-full w-screen overflow-x-auto">
        <div
          id="main-content"
          className="bg-term-light-blue w-fit min-h-screen"
        >
          {/* The interface, including the background, stars, error message, and main terminal to input values into. */}
          <TerminusBackgroundWrapper showHelpIcon>
            {/* Stars */}
            <TerminusStars
              puzzles={starPuzzles}
              response={updateTerminusResponse}
              teamState={teamState}
            />
            {/* Main content */}
            <form
              onSubmit={(e) => {
                e.preventDefault();
                handleUpdateTerminusSubmit(inputValue);
              }}
            >
              <TerminusInteractiveScreens
                response={updateTerminusResponse}
                state={interfaceState}
                rateLimitEndTimestamp={rateLimitEndTimestamp}
                isLoading={updateTerminusLoading}
                clientError={clientError}
                inputValue={inputValue}
                setInputValue={setInputValue}
              />
            </form>
            {/* Errors */}
            <TerminusMessages response={updateTerminusResponse} />
          </TerminusBackgroundWrapper>
          <TerminusPuzzleList
            state={listState}
            teamState={teamState}
            showAllPuzzles={IS_STATIC_SITE ? showAllPuzzles : undefined}
            onToggleShowAll={() => {
              setShowAllPuzzles((prev) => !prev);
            }}
          />
        </div>
      </div>
      <CutsceneDisplay content={cutsceneContent} />
    </TeamStateProvider>
  );
};

export default TerminusBody;
