/**
 * Helper function to get the region for a slot ID.
 * Returns null if the slot doesn't have a region assigned (e.g., final meta).
 */
export const getRegionForPuzzle = (
  puzzleSlug: string,
  teamState: TeamHuntState,
): number | null => {
  const slotEntry = Object.entries(teamState.rounds.terminus.slots).find(
    ([, slotData]) => slotData.slug === puzzleSlug,
  );
  if (!slotEntry) return null;
  const [slotId] = slotEntry;
  // Safe to pass: slotId comes from teamState.rounds.terminus.slots which only contains valid TerminusSlot values
  return SLOT_TO_PUZZLE_DATA[slotId as TerminusSlot]?.region ?? null;
};
